import Select from "react-dropdown-select";
import { useEffect, useState } from "react";
import axios from "axios";

export default function SearchDropdown({ onChange }) {
  const [options, setOptions] = useState([]);

  useEffect(() => {
    axios.get("https://releasetrain.io/api/c/names").then(res => {
      const formatted = res.data.map(name => ({ label: name, value: name }));
      setOptions(formatted);
    });
  }, []);

  return (
    <Select
      multi
      options={options}
      onChange={(values) => onChange(values.map(v => v.value))}
      placeholder="Select software components"
      style={{ marginBottom: "1rem" }}
    />
  );
}
